// validateLineText 在 JSON 解析之前强制整行文本合法：原始字节必须是合法
// UTF-8，字符串内的 Unicode 转义必须表示有效字符。编码层/JSON 解析器会把
// 非法字节或未配对代理项静默替换成 U+FFFD，使损坏文本混入合法序列（被误判为
// 重复、冲突或错误命中查询），因此这里一律拒绝而不是修补后继续。
//
// 仅检查字符串内部的 \u 转义：跳过词法空白与全部非字符串 token；被转义的
// 反斜杠（\\）后的 "uXXXX" 只是普通文本，不会被当成转义。字符串外的 \uXXXX
// 在合法 JSON 中本就不可能出现，交由 JSON 解析报错。
func validateLineText(line string) *LineError {
	if !utf8.ValidString(line) {
		return &LineError{Status: "error", Error: "invalid JSON: input is not valid UTF-8 text"}
	}
	inString := false
	escaped := false // 字符串内上一个字符为未成对的反斜杠
	for i := 0; i < len(line); i++ {
		c := line[i]
		if !inString {
			if c == '"' {
				inString = true
				escaped = false
			}
			continue
		}
		if escaped {
			escaped = false
			continue
		}
		switch c {
		case '\\':
			escaped = true
		case '"':
			inString = false
		case 'u':
			// 仅在反斜杠转义上下文中到达这里（前一字符是未成对的 '\\' 已被
			// 翻转 escaped 处理：\\u 走 \\ 分支置 escaped，随后的 u 被跳过）。
			if i > 0 && line[i-1] == '\\' {
				r, size := decodeJSONHexEscape(line, i)
				if size == 0 {
					return &LineError{Status: "error", Error: "invalid JSON: invalid Unicode escape sequence"}
				}
				if utf16.IsSurrogate(r) {
					// 高代理项后必须紧接合法的低代理项转义；单独的高/低代理项
					// 或高代理项后缺少合法低代理项都拒绝整行。
					lo, loSize := decodeJSONHexEscape(line, i+size)
					if r >= 0xDC00 || loSize == 0 || !utf16.IsLowSurrogate(lo) {
						return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
					}
					i += size + loSize - 1
				} else {
					i += size - 1
				}
			}
		}
	}
	return nil
}

// decodeJSONHexEscape 解析 line[pos:] 处的 "uXXXX"（pos 指向 'u'），
// 返回其码元与占用字节数（固定为 5）；不是四个十六进制数字时 size 为 0。
func decodeJSONHexEscape(line string, pos int) (rune, int) {
	if pos+4 >= len(line) {
		return 0, 0
	}
	var v rune
	for j := pos + 1; j <= pos+4; j++ {
		c := line[j]
		var d rune
		switch {
		case c >= '0' && c <= '9':
			d = rune(c - '0')
		case c >= 'a' && c <= 'f':
			d = rune(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = rune(c-'A') + 10
		default:
			return 0, 0
		}
		v = v<<4 | d
	}
	return v, 5
}

