package main

import (
	"encoding/json"
	"fmt"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

func main() {
	s := darksafe.NewMetricStore()

	// Seed a REAL U+FFFD series and a normal one.
	r, e := s.IngestLine(`[{"name":"m�","timestamp":1,"value":7}]`)
	fmt.Printf("seed FFFD series: ok=%v err=%v\n", r != nil, e)

	check := func(label, line string) {
		_, e := s.IngestLine(line)
		if e == nil {
			fmt.Printf("%s: UNEXPECTED SUCCESS\n", label)
			return
		}
		fmt.Printf("%s: REJECT index=%d err=%q\n", label, e.Index, e.Error)
	}

	// --- corrupt writes must be whole-line failures ---
	check("lone high \\uD800", `[{"name":"m\uD800","timestamp":1,"value":1}]`)
	check("lone low \\uDC00", `[{"name":"m\uDC00","timestamp":1,"value":1}]`)
	check("high+non-low", `[{"name":"m\uD800A","timestamp":1,"value":1}]`)
	check("escaped backslash then uD800 (valid)", `[{"name":"m\\uD800","timestamp":1,"value":1}]`)
	check("valid pair (supplementary)", `[{"name":"m😀","timestamp":1,"value":1}]`)
	check("explicit FFFD escape == real FFFD", `[{"name":"m�","timestamp":1,"value":7}]`)

	// raw invalid utf8 bytes in name / label key / label value
