	res := mustOK(t, store, `[{"name":"m","timestamp":1,"value":1.0,"labels":{"机房":"","区域":"华东"}}]`)
	if res.Added != 0 || res.Duplicates != 1 {
		t.Fatalf("label order with unicode must not change identity, got %+v", res)
