	qr := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":10,"labels":{"区域":"华东"}}`)
	if len(qr.Series) != 1 || qr.Series[0].Average != 1 {
		t.Fatalf("unicode subset label match failed: %+v", qr.Series)
