	qr = mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":10,"labels":{"机房":""}}`)
	if len(qr.Series) != 1 {
		t.Fatalf("empty unicode label value must match, got %+v", qr.Series)
	}
}

func TestProcessLineConsistentAcrossEntries(t *testing.T) {
